/* Shared browser-local programme selection. Programme IDs and allowlisted costume choices persist here. */
(()=>{'use strict';
const key='teatr.holiday.v1',valid=new Set(Object.values(window.TEATR_CATALOG).flatMap(c=>c.programs.map(p=>p.id)));
const costumes={'crystal-story':['elf','snow-maiden'],'winter-lab':['elf','frost','snow-maiden'],'snow-whirl':['elves','frost-maiden'],'new-year':['frost-maiden'],'christmas-tree':['frost-maiden','elves'],'ice-adventure':['frost-maiden','elves'],'santa-workshop':['frost-maiden','elves']};
let memory={cart:[],favorites:[]},unpersisted=false;
const clean=v=>{const out={cart:[...new Set(Array.isArray(v?.cart)?v.cart:[])].filter(id=>valid.has(id)),favorites:[...new Set(Array.isArray(v?.favorites)?v.favorites:[])].filter(id=>valid.has(id))};for(const [id,allowed]of Object.entries(costumes)){const costume=v?.options?.[id]?.costume;if(allowed.includes(costume)){out.options??={};out.options[id]={costume}}}const variant=v?.options?.['snow-whirl']?.variant;if(['standard','vip'].includes(variant)){out.options??={};out.options['snow-whirl']={...out.options['snow-whirl'],variant}}if(window.ComboPricing)for(const id of window.ComboPricing.ids){if(v?.options?.[id]?.combo){out.options??={};out.options[id]={combo:window.ComboPricing.clean(v.options[id].combo)}}}return out};
function read(){if(unpersisted)return clean(memory);try{memory=clean(JSON.parse(localStorage.getItem(key)||'null'))}catch{}return clean(memory)}
function write(next){memory=clean(next);try{localStorage.setItem(key,JSON.stringify(memory));unpersisted=false}catch{unpersisted=true}window.dispatchEvent(new Event('holidaychange'));return read()}
window.HolidayStore={read,setCombo(id,options){if(!window.ComboPricing?.ids.includes(id))return;const v=read();v.options={...v.options,[id]:{combo:window.ComboPricing.clean(options)}};if(!v.cart.includes(id))v.cart.push(id);return write(v)},variant(id){return id==='snow-whirl'?(read().options?.[id]?.variant||'standard'):null},setVariant(id,variant){if(id!=='snow-whirl'||!['standard','vip'].includes(variant))return;const v=read();v.options={...v.options,[id]:{...v.options?.[id],variant}};return write(v)},costume(id){return costumes[id]?(read().options?.[id]?.costume||(costumes[id]?.includes('frost-maiden')?'frost-maiden':'snow-maiden')):null},setCostume(id,costume){if(!costumes[id]?.includes(costume))return;const v=read();v.options={...v.options,[id]:{...v.options?.[id],costume}};return write(v)},has:(type,id)=>read()[type]?.includes(id)||false,add(id){if(!valid.has(id))return;const v=read();if(!v.cart.includes(id))v.cart.push(id);if(costumes[id])v.options={...v.options,[id]:{...v.options?.[id],costume:v.options?.[id]?.costume||(costumes[id]?.includes('frost-maiden')?'frost-maiden':'snow-maiden'),...(id==='snow-whirl'?{variant:v.options?.[id]?.variant||'standard'}:{})}};return write(v)},remove(id){const v=read();v.cart=v.cart.filter(x=>x!==id);return write(v)},favorite(id){if(!valid.has(id))return;const v=read();v.favorites=v.favorites.includes(id)?v.favorites.filter(x=>x!==id):[...v.favorites,id];return write(v)},clearCart(){const v=read();v.cart=[];return write(v)}};
window.addEventListener('storage',e=>{if(e.key===key)window.dispatchEvent(new Event('holidaychange'))});
})();
